/* READ ONLY Teradata SQL Assistant. Run each numbered SELECT separately.
Full populations, no account sample; no permanent tables/config/run changes.
Uses the analyst-confirmed numeric special list. Counts are account-month events.
Keep the source fixed and reconcile baseline counts to saved results first.
FLOAT casts precede arithmetic. NULL numeric outputs indicate invalid source grain;
absence of rows is not a pass. No individual account results should be uploaded.
*/
/* Top 0.1% is a diagnostic cohort, not a removal rule. Plateau and case-level jumps are different tests. Agree source value scale; high SD alone is not an error. */
WITH src AS (SELECT AGMT_ID,CAST(FACT_DT AS DATE) AS POU_DT,CAST(PCKG_BOVO_VAL_AMT AS FLOAT) AS V,COUNT(*) OVER (PARTITION BY AGMT_ID,EXTRACT(YEAR FROM FACT_DT),EXTRACT(MONTH FROM FACT_DT)) AS KC FROM LAB_T_ORION_MVT.VW_RDS_PHASE2_FACT WHERE FACT_DT>=DATE '2008-01-01' AND FACT_DT<DATE '2014-01-01'),
ctl AS (SELECT POU_DT,SUM(CASE WHEN AGMT_ID IS NULL OR KC<>1 THEN 1 ELSE 0 END) AS BAD FROM src GROUP BY POU_DT),
r AS (SELECT S.*,ROW_NUMBER() OVER (PARTITION BY POU_DT ORDER BY ABS(V) DESC,AGMT_ID) AS RN,COUNT(*) OVER (PARTITION BY POU_DT) AS N FROM src S WHERE V IS NOT NULL AND V NOT IN (-99999,-999999,-999998,-99998,-99997,-9999,-9998,-999997,-999993,-999,-999995,999999,999998,999990,99999,99998,999.99,999.88,999,9999,9998)),
a AS (SELECT POU_DT,COUNT(*) AS VALID_COUNT,AVG(V) AS MEAN_ALL,STDDEV_POP(V) AS STDDEV_ALL,MAX(V) AS MAX_VALUE,SUM(CASE WHEN RN<=CEILING(N*CAST(0.001 AS FLOAT)) THEN 1 ELSE 0 END) AS TOP_01PCT_COUNT,AVG(CASE WHEN RN>CEILING(N*CAST(0.001 AS FLOAT)) THEN V END) AS MEAN_WITHOUT_TAIL,STDDEV_POP(CASE WHEN RN>CEILING(N*CAST(0.001 AS FLOAT)) THEN V END) AS STDDEV_WITHOUT_TAIL FROM r GROUP BY POU_DT)
SELECT C.POU_DT,CASE WHEN BAD=0 THEN VALID_COUNT END AS VALID_COUNT,
 CASE WHEN BAD=0 THEN MEAN_ALL END AS MEAN_ALL,CASE WHEN BAD=0 THEN STDDEV_ALL END AS STDDEV_ALL,
 CASE WHEN BAD=0 THEN MAX_VALUE END AS MAX_VALUE,CASE WHEN BAD=0 THEN TOP_01PCT_COUNT END AS TOP_01PCT_COUNT,
 CASE WHEN BAD=0 THEN MEAN_WITHOUT_TAIL END AS MEAN_WITHOUT_TAIL,CASE WHEN BAD=0 THEN STDDEV_WITHOUT_TAIL END AS STDDEV_WITHOUT_TAIL
FROM ctl C LEFT JOIN a ON C.POU_DT=a.POU_DT ORDER BY C.POU_DT;
